WITH latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY category ORDER BY stock_qty DESC NULLS LAST) AS rn FROM products) ranked WHERE rn = 1), with_last AS (SELECT s.*, latest.unit_price, latest.order_item_quantity FROM latest s LEFT JOIN LATERAL (SELECT c.unit_price, c.quantity AS order_item_quantity FROM order_items c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) latest ON TRUE), joined AS (SELECT a.id, a.product_name, a.category, a.price, a.cost, a.tags, a.supplier_id, a.order_item_quantity, s.country, s.city FROM with_last a JOIN suppliers s ON a.supplier_id = s.id), with_latest AS (SELECT s.id, s.category, s.price, s.tags, s.order_item_quantity, top1.unit_price, top1.quantity FROM joined s JOIN LATERAL (SELECT c.unit_price, c.quantity FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) top1 ON TRUE), not_flagged AS (SELECT s.* FROM with_latest s WHERE EXISTS (SELECT 1 FROM store_sales c WHERE c.product_id = s.id AND c.store_id IN (1, 2, 5, 6))) SELECT id, category, tags, quantity FROM not_flagged
